'use strict';

(function ($) {

    /*------------------
        Preloader
    --------------------*/
    $(window).on('load', function () {
        $(".loader").fadeOut();
        $("#preloder").delay(200).fadeOut("slow");
    });

    /*------------------
        Background Set
    --------------------*/
    $('.set-bg').each(function () {
        var bg = $(this).data('setbg');
        $(this).css('background-image', 'url(' + bg + ')');
    });

    //Canvas Menu
    $(".canvas__open").on('click', function () {
        $(".offcanvas-menu-wrapper").addClass("active");
        $(".offcanvas-menu-overlay").addClass("active");
    });

    $(".offcanvas-menu-overlay").on('click', function () {
        $(".offcanvas-menu-wrapper").removeClass("active");
        $(".offcanvas-menu-overlay").removeClass("active");
    });

    //Search Switch
    $('.search-switch').on('click', function () {
        $('.search-model').fadeIn(400);
    });

    $('.search-close-switch').on('click', function () {
        $('.search-model').fadeOut(400, function () {
            $('#search-input').val('');
        });
    });

    //Accordin Active
    $('.collapse').on('shown.bs.collapse', function () {
        $(this).prev().addClass('active');
    });

    $('.collapse').on('hidden.bs.collapse', function () {
        $(this).prev().removeClass('active');
    });

    /*------------------
        Navigation
    --------------------*/
    $(".mobile-menu").slicknav({
        prependTo: '#mobile-menu-wrap',
        allowParentLinks: true
    });

    /*--------------------------
        Testimonial Slider
    ----------------------------*/
    var testimonialSlider = $(".testimonial__slider");
    testimonialSlider.owlCarousel({
        loop: true,
        margin: 0,
        items: 3,
        dots: true,
        smartSpeed: 1200,
        autoHeight: false,
        autoplay: false,
        responsive: {
            992: {
                items: 3
            },
            768: {
                items: 2
            },
            320: {
                items: 1
            }
        }
    });

    /*-----------------------------
        Blog Details Slider
    -------------------------------*/
    $(".blog__details__slider").owlCarousel({
        loop: true,
        margin: 0,
        items: 1,
        dots: false,
        nav: true,
        navText: ["<i class='fa fa-long-arrow-left'></i>", "<i class='fa fa-long-arrow-right'></i>"],
        smartSpeed: 1200,
        autoHeight: false,
        autoplay: true,
    });

    /*-----------------------
        Range Slider
    ------------------------ */
    var rangeSliderPrice = $(".price-range"),
        price = $("#price");
    rangeSliderPrice.slider({
        range: 'min',
        min: 0,
        max: 3800000,
        value: 2458000,
        slide: function (event, ui) {
            price.val(ui.value);
        }
    });
    price.val(rangeSliderPrice.slider("value"));

    var rangeSliderPrice = $(".price-range-month"),
        month = $("#month");
    rangeSliderPrice.slider({
        range: 'min',
        min: 0,
        max: 10,
        value: 4,
        slide: function (event, ui) {
            month.val(ui.value);
        }
    });
    month.val(rangeSliderPrice.slider("value"));

    var rangeSliderPrice = $(".price-range-percent"),
        percent = $("#percent");
    rangeSliderPrice.slider({
        range: 'min',
        min: 0,
        max: 72,
        value: 18,
        slide: function (event, ui) {
            percent.val(ui.value + ' Percent');
        }
    });
    percent.val(rangeSliderPrice.slider("value") + ' Percent');




    /*--------------------------
        Select
    ----------------------------*/
    //$("select").niceSelect();
    // $(function() {
    //     $('.chosen-select').chosen();
    //     $('.chosen-select-deselect').chosen({ allow_single_deselect: true });
    //   });
    // $('select').extendSelect();


    $(".nice-scroll").niceScroll({
        cursorcolor: "rgba(135, 196, 23, 0.3)",
        cursorwidth: "6px",
        background: "rgba(255, 255, 255, 0.1)",
        cursorborder: "",
        autohidemode: false,
        horizrailenabled: false
    });
    $('.video-popup').magnificPopup({
        type: 'iframe'
    });
    $('.counter-add').each(function () {
        $(this).prop('Counter', 0).animate({
            Counter: $(this).text()
        }, {
            duration: 4000,
            easing: 'swing',
            step: function (now) {
                $(this).text(Math.ceil(now));
            }
        });
    });

})(jQuery);

// assets/js/infiniteslidev2.js
(function($){
    $(window).on('load', function() {
        window.loaded = true;
    });
    $(function(){
        $.fn.infiniteslide = function(options){
            //option
            var settings = $.extend({
                'speed': 100, //速さ　単位はpx/秒です。
                'direction': 'left', //up/down/left/rightから選択
                'pauseonhover': true, //マウスオーバーでストップ
                'responsive': false, //子要素の幅を%で指定しているとき
                'clone': 1
            },options);

            var setCss = function(obj,direction){
                $(obj).wrap('<div class="infiniteslide_wrap"></div>').parent().css({
                    overflow: 'hidden'
                });

                if(direction == 'up' || direction == 'down'){
                    var d = 'column';
                } else {
                    var d = 'row';
                }

                $(obj).css({
                    display: 'flex',
                    flexWrap: 'nowrap',
                    alignItems: 'center',
                    '-ms-flex-align': 'center',
                    flexDirection: d
                }).children().css({
                        flex: 'none',
                        display: 'block'
                    });
            }

            var setClone = function(obj,clone){
                var $clone = $(obj).children().clone().addClass('infiniteslide_clone');
                i = 1;
                while(i <= clone){
                    $clone.clone().appendTo($(obj));
                    i++;
                }
            }

            var getWidth = function(obj){
                w = 0;
                $(obj).children(':not(.infiniteslide_clone)').each(function(key,value){
                    w = w + $(this).outerWidth(true);
                });
                return w;
            }
            var getHeight = function(obj){
                h = 0;
                $(obj).children(':not(.infiniteslide_clone)').each(function(key,value){
                    h = h + $(this).outerHeight(true);
                });
                return h;
            }


            var getSpeed = function(l,s){
                return l / s;
            }
            var getNum = function(obj,direction){
                if(direction == 'up' || direction == 'down'){
                    var num = getHeight(obj);
                } else {
                    var num = getWidth(obj);
                }
                return num;
            }

            var getTranslate = function(num,direction){
                if(direction == 'up' || direction == 'down'){
                    var i = '0,-' + num + 'px,0';
                } else {
                    var i = '-' + num + 'px,0,0';
                }
                return i;
            }

            var setAnim = function(obj,id,direction,speed){
                var num = getNum(obj,direction);
                if(direction == 'up' || direction == 'down'){
                    $(obj).parent('.infiniteslide_wrap').css({
                        height: num + 'px'
                    });
                }
                var i = getTranslate(num,direction);

                $(obj).attr('data-style','infiniteslide' + id);

                var css = '@keyframes infiniteslide' + id + '{' +
                                'from {transform:translate3d(0,0,0);}' +
                                'to {transform:translate3d(' + i + ');}' +
                            '}';
                $('<style />').attr('id','infiniteslide' + id + '_style')
                .html(css)
                .appendTo('head');

                if(direction == 'right' || direction == 'down'){
                    var reverse = ' reverse';
                } else {
                    var reverse = '';
                }

                $(obj).css({
                    animation: 'infiniteslide' + id + ' ' + getSpeed(num,speed) + 's linear 0s infinite' + reverse
                });
            }
            var setStop = function(obj){
                $(obj).on('mouseenter',function(){
                    $(this).css({
                        animationPlayState: 'paused'
                    });
                }).on('mouseleave',function(){
                    $(this).css({
                        animationPlayState: 'running'
                    });
                });
            }

            var setResponsive = function(obj,direction){
                    var num = getNum(obj,direction);
                    var i = getTranslate(num,direction);
                    return i;
                };




            return this.each(function(key,value){
                var $this = $(this);
                var num = Date.now() + Math.floor(10000*Math.random()).toString(16);
                if(settings.pauseonhover == true){
                    setStop($this);
                }
                var _onload = function(){
                    setCss($this,settings.direction);
                    setClone($this,settings.clone);
                    setAnim($this,num,settings.direction,settings.speed);

                    if(settings.responsive){
                        $(window).on('resize',function(){
                            var i = setResponsive($this,settings.direction);
                            var styleid = $this.attr('data-style');
                            var stylehtml = $('#' + styleid + '_style').html();

                            var stylehtml_new = stylehtml.replace(/to {transform:translate3d\((.*?)\)/,'to {transform:translate3d(' + i + ')');
                            $('#' + styleid + '_style').html(stylehtml_new);

                        });
                    }
                };

                if (window.loaded) {
                    _onload();
                } else {
                    $(window).on('load', _onload);
                }
            });

        }
    });
})(jQuery);

